$ErrorActionPreference="Stop"
$D="$env:ProgramData\OfficeDeploy";$R="https://raw.githubusercontent.com/alamaxjashek/OfficeDeploy/main";New-Item $D -ItemType Directory -Force|Out-Null
$Log="$D\uninstall.log";Start-Transcript -Path $Log -Append -Force|Out-Null;$ExitCode=0
try{$Roots=@("HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*","HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*");Write-Host "=== 0. VERIFICANDO REINICIO PENDIENTE ===";$RP=(Test-Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending") -or (Test-Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired") -or ($null -ne (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager" -Name PendingFileRenameOperations -ErrorAction SilentlyContinue));if($RP){Write-Host "REINICIO PENDIENTE. Reinicie Windows y vuelva a ejecutar." -ForegroundColor Yellow;$ExitCode=3010}else{Write-Host "=== 1. CERRANDO APLICACIONES OFFICE ===";Get-Process WINWORD,EXCEL,OUTLOOK,POWERPNT,MSACCESS,MSPUB,ONENOTE,VISIO,WINPROJ -ErrorAction SilentlyContinue|Stop-Process -Force -ErrorAction SilentlyContinue;Write-Host "=== 2. CLICK-TO-RUN / ODT ===";$C2R=(Test-Path "HKLM:\SOFTWARE\Microsoft\Office\ClickToRun\Configuration") -or (Test-Path "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Office\ClickToRun\Configuration");if($C2R){Write-Host "Office Click-to-Run detectado. Ejecutando ODT...";Invoke-WebRequest "$R/setup.exe" -OutFile "$D\setup.exe";Invoke-WebRequest "$R/uninstall.xml" -OutFile "$D\uninstall.xml";$O=Start-Process "$D\setup.exe" -ArgumentList "/configure `"$D\uninstall.xml`"" -Wait -PassThru -NoNewWindow;if($O.ExitCode -eq 0){Write-Host "ODT: Click-to-Run eliminado correctamente." -ForegroundColor Green}elseif($O.ExitCode -eq 3010){Write-Host "ODT: eliminado, reinicio requerido." -ForegroundColor Yellow;$ExitCode=3010}elseif($O.ExitCode -eq -1){Write-Host "ODT: no habia producto Click-to-Run aplicable o no fue necesaria ninguna accion." -ForegroundColor DarkGray}else{Write-Warning "ODT devolvio ExitCode $($O.ExitCode)"}}else{Write-Host "No se detecto Office Click-to-Run. ODT omitido." -ForegroundColor DarkGray};Write-Host "=== 3. OFFICE MSI 2007-2016 ===";$Pattern="(?i)(Office|Visio|Project|Access|Excel|Word|PowerPoint|Outlook|Publisher|OneNote).*(2007|2010|2013|2016)";$Items=@(Get-ItemProperty $Roots -ErrorAction SilentlyContinue|Where-Object{$_.Publisher -like "Microsoft*" -and $_.DisplayName -match $Pattern -and $_.PSChildName -match "^\{[0-9A-Fa-f-]+\}$"});$NeedScrub=$false;foreach($I in ($Items|Sort-Object PSChildName -Unique)){Write-Host "Desinstalando: $($I.DisplayName) [$($I.PSChildName)]";$Code=$I.PSChildName -replace "[{}]","";$ML="$D\MSI-$Code.log";$M=Start-Process msiexec.exe -ArgumentList "/x `"$($I.PSChildName)`" /qn /norestart /L*v `"$ML`"" -Wait -PassThru;Write-Host "MSI ExitCode: $($M.ExitCode)";if($M.ExitCode -eq 1603){$NeedScrub=$true}elseif($M.ExitCode -eq 3010){$ExitCode=3010}elseif($M.ExitCode -notin @(0,1605)){Write-Warning "MSI fallo con codigo $($M.ExitCode): $($I.DisplayName)"}};if($NeedScrub){Write-Host "=== 4. OFFICE SCRUB MICROSOFT ===" -ForegroundColor Yellow;$SD="$D\GetHelpCmd";Remove-Item $SD -Recurse -Force -ErrorAction SilentlyContinue;New-Item $SD -ItemType Directory -Force|Out-Null;$Z="$SD\GetHelpCmd.zip";Invoke-WebRequest "https://download.microsoft.com/download/d749c6af-d25e-42f2-afe1-19c979f4c734/GetHelpCmd_146630116.zip" -OutFile $Z;Expand-Archive $Z -DestinationPath $SD -Force;$GH=Get-ChildItem $SD -Filter GetHelpCmd.exe -Recurse|Select-Object -First 1 -ExpandProperty FullName;if(!$GH){throw "No se encontro GetHelpCmd.exe"};Write-Host "Ejecutando Microsoft OfficeScrubScenario...";& $GH -S OfficeScrubScenario -AcceptEula;Write-Host "Esperando desinstalacion en segundo plano...";$Timeout=(Get-Date).AddMinutes(30);do{Start-Sleep -Seconds 15;$Old=@(Get-ItemProperty $Roots -ErrorAction SilentlyContinue|Where-Object{$_.DisplayName -match "(?i)Office Professional( Plus)? (2007|2010|2013|2016)"});$OldExe=@("C:\Program Files\Microsoft Office\Office16\WINWORD.EXE","C:\Program Files (x86)\Microsoft Office\Office16\WINWORD.EXE","C:\Program Files\Microsoft Office\Office15\WINWORD.EXE","C:\Program Files (x86)\Microsoft Office\Office15\WINWORD.EXE","C:\Program Files\Microsoft Office\Office14\WINWORD.EXE","C:\Program Files (x86)\Microsoft Office\Office14\WINWORD.EXE")|Where-Object{Test-Path $_}}while(($Old.Count -gt 0 -or $OldExe.Count -gt 0) -and (Get-Date) -lt $Timeout)};Write-Host "=== 5. VERIFICACION FINAL ===";$Left=@(Get-ItemProperty $Roots -ErrorAction SilentlyContinue|Where-Object{$_.DisplayName -match "(?i)Office Professional( Plus)? (2007|2010|2013|2016)"});$Exe=@("C:\Program Files\Microsoft Office\Office16\WINWORD.EXE","C:\Program Files (x86)\Microsoft Office\Office16\WINWORD.EXE","C:\Program Files\Microsoft Office\Office15\WINWORD.EXE","C:\Program Files (x86)\Microsoft Office\Office15\WINWORD.EXE","C:\Program Files\Microsoft Office\Office14\WINWORD.EXE","C:\Program Files (x86)\Microsoft Office\Office14\WINWORD.EXE")|Where-Object{Test-Path $_};$RealMSI=@($Left|Where-Object{$_.PSChildName -match "^\{[0-9A-Fa-f-]+\}$"});if($RealMSI.Count -eq 0 -and $Exe.Count -eq 0){$Orphans=@($Left|Where-Object{$_.PSChildName -notmatch "^\{[0-9A-Fa-f-]+\}$"});foreach($X in $Orphans){Write-Host "Eliminando entrada huerfana: $($X.DisplayName) [$($X.PSChildName)]" -ForegroundColor Yellow;Remove-Item $X.PSPath -Recurse -Force -ErrorAction SilentlyContinue};$Left=@(Get-ItemProperty $Roots -ErrorAction SilentlyContinue|Where-Object{$_.DisplayName -match "(?i)Office Professional( Plus)? (2007|2010|2013|2016)"})};if($Left.Count -gt 0 -or $Exe.Count -gt 0){Write-Host "QUEDAN COMPONENTES OFFICE:" -ForegroundColor Red;$Left|Select DisplayName,DisplayVersion,PSChildName|Format-Table -AutoSize;$Exe|ForEach-Object{Write-Host "EXISTE: $_" -ForegroundColor Red};$ExitCode=1}elseif($ExitCode -ne 3010){Write-Host "OFFICE ANTIGUO ELIMINADO CORRECTAMENTE." -ForegroundColor Green}}}catch{Write-Host "ERROR: $($_.Exception.Message)" -ForegroundColor Red;$ExitCode=1}finally{Stop-Transcript -ErrorAction SilentlyContinue};exit $ExitCode